package br.com.onda;
import android.app.*;
import android.content.*;
import android.database.Cursor;
import android.net.Uri;
import android.os.*;
import android.provider.*;
import android.view.*;
import android.widget.*;
import java.util.concurrent.*;

@androidx.media3.common.util.UnstableApi
public class LocalConverterActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private Uri source,waitingTarget;private String title="Áudio convertido",format;private TextView status;private Button mp3,m4a;private boolean busy;private int generation;
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,20),Ui.dp(this,12)+i.getSystemWindowInsetTop(),Ui.dp(this,20),Ui.dp(this,12)+i.getSystemWindowInsetBottom());return i;});setContentView(root);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.addView(Ui.button(this,"‹",v->finish()),new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));bar.addView(Ui.text(this,"Conversor local",22,Ui.TEXT),new LinearLayout.LayoutParams(0,-2,1));root.addView(bar);ScrollView scroll=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));TextView intro=Ui.text(this,"Extraia o áudio de um vídeo ou converta um áudio AAC do celular. O arquivo original é preservado. Processamento no aparelho, sem API paga.",15,Ui.MUTED);intro.setPadding(0,20,0,20);body.addView(intro);body.addView(Ui.button(this,"Escolher vídeo ou áudio",v->choose()));status=Ui.text(this,"Escolha um arquivo para conferir a compatibilidade.",14,Ui.CYAN);status.setPadding(0,20,0,20);body.addView(status);mp3=Ui.button(this,"Converter para MP3 • 192 kbps",v->save("mp3"));m4a=Ui.button(this,"Extrair M4A • sem recodificar",v->save("m4a"));body.addView(mp3);body.addView(m4a);mp3.setEnabled(false);m4a.setEnabled(false);body.addView(Ui.button(this,"Acompanhar na Central",v->startActivity(new Intent(this,DownloadCenterActivity.class))));body.addView(Ui.text(this,"Compatibilidade inicial: áudio AAC em MP4, M4A e AAC, conforme o aparelho. MP3 exige recodificação e não aumenta a qualidade da fonte. M4A conserva a faixa AAC. Até 512 MB por arquivo e 30 minutos de operação. Escolha o destino ou use a pasta Onda/Áudios configurada na Central.",13,Ui.MUTED));if(state!=null){format=state.getString("format");String uri=state.getString("source");title=state.getString("title",title);if(uri!=null)inspect(Uri.parse(uri));}else{String uri=getIntent().getStringExtra("local_source");if(uri!=null)inspect(Uri.parse(uri));}}
 private void choose(){if(busy||MediaDownloadService.activeDownload){Toast.makeText(this,"Aguarde a operação atual",Toast.LENGTH_SHORT).show();return;}try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"audio/*","video/*"}).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),801);}catch(Exception e){status.setText("Seletor de arquivos indisponível.");}}
 private void inspect(Uri uri){int request=++generation;source=null;mp3.setEnabled(false);m4a.setEnabled(false);status.setText("Conferindo áudio do arquivo…");worker.execute(()->{try{String info=LocalAudio.inspect(this,uri),name="Áudio convertido";try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(c!=null&&c.moveToFirst()){name=c.getString(0);if(!c.isNull(1)&&c.getLong(1)>LocalAudio.MAX)throw new java.io.IOException("Arquivo excede 512 MB");}}String label=name==null?"Áudio convertido":name;runOnUiThread(()->{if(isDestroyed()||request!=generation)return;source=uri;title=label.replaceFirst("(?i)\\.[a-z0-9]{1,8}$","");status.setText(label+"\n"+info);mp3.setEnabled(true);m4a.setEnabled(true);if(waitingTarget!=null){Uri destination=waitingTarget;waitingTarget=null;start(destination);}});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed()&&request==generation){if(waitingTarget!=null){delete(waitingTarget);waitingTarget=null;}status.setText(e.getMessage());}});}});}
 private void save(String selected){if(source==null||busy||MediaDownloadService.activeDownload)return;format=selected;if(OndaFolders.enabled(this)){new AlertDialog.Builder(this).setTitle("Salvar conversão").setMessage("Criar um novo arquivo em Onda/Áudios?").setPositiveButton("Salvar na pasta Onda",(d,w)->{busy=true;worker.execute(()->{try{Uri target=OndaFolders.create(this,selected,title);runOnUiThread(()->{if(isDestroyed()){delete(target);return;}start(target);});}catch(Exception e){runOnUiThread(()->{busy=false;if(!isDestroyed())status.setText("Sem acesso à pasta do Onda. Escolha outro local ou configure a pasta na Central.");});}});}).setNeutralButton("Outro local",(d,w)->destination()).setNegativeButton("Cancelar",null).show();}else destination();}
 private void destination(){busy=true;try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(MediaDownloadService.mime(format)).putExtra(Intent.EXTRA_TITLE,DownloadLinks.filename(title)+"."+format),802);}catch(Exception e){busy=false;status.setText("Não foi possível escolher o destino.");}}
 private void delete(Uri target){try{DocumentsContract.deleteDocument(getContentResolver(),target);}catch(Exception ignored){}}
 private void start(Uri target){busy=false;if(source==null||MediaDownloadService.activeDownload){delete(target);status.setText("Há outra operação em andamento. Tente novamente ao terminar.");return;}try{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},803);startForegroundService(new Intent(this,MediaDownloadService.class).putExtra("conversion_source",source.toString()).putExtra("destination",target.toString()).putExtra("format",format).putExtra("title",title));startActivity(new Intent(this,DownloadCenterActivity.class));}catch(Exception e){delete(target);status.setText("O Android não permitiu iniciar a conversão.");}}
 @Override public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==802){busy=false;if(result==RESULT_OK&&data!=null&&data.getData()!=null){if(source==null)waitingTarget=data.getData();else start(data.getData());}}else if(request==801&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}inspect(uri);}}
 @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(source!=null)state.putString("source",source.toString());state.putString("format",format);state.putString("title",title);}@Override public void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
